/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: LookupPlanInput, PlannedLookupQuery, LookupPlan
 *   Functions: isFallbackLookupQuery, normalizedLookupTitle, isCompanyLikeName, splitCreditedNames,
 *              cleanFolderName, planMetadataLookup
 * Internal
 *   Functions: term, tagTerm, buildable, canonical
 *   Constants: waveDash, soundTrack, remasterNote, companySuffix, japaneseCompany, formatToken
 * @end-catalog */

import { METADATA_LOOKUP_LIMITS } from './lookupContract';
import { cleanLookupTerm, isPlaceholderCredit, lookupTermProblem, normalizeGtin, normalizeIsrc, normalizeMusicBrainzId } from './lookupIdentifiers';
import { musicBrainzLuceneQuery, type MusicBrainzRecordingQuery, type MusicBrainzReleaseQuery } from './musicBrainzClient';

/**
 * Pure planner from an import's evidence, or an existing-Album review's saved Album title and primary
 * Artist names, to at most six MusicBrainz queries: valid embedded identifiers first, then album or
 * song text, then a cleaned folder name. It accepts names, never links or file names; an identifier
 * that fails its format check is dropped and never sent. Submitted text is only normalized (NFC,
 * collapsed whitespace), so a link, an over-long name or a control or format character rejects the
 * plan; tag, folder and saved-title text is cleaned instead. Queries carry only that text, its credited
 * names and the identifiers; the file count is never sent (the run uses it locally, lookupRunStep.ts).
 * Fallback queries follow the text searches, sent only when those found nothing: tag, folder or saved
 * title text in its normalized spelling (NFKC, the wave dash as `~`, "Sound Track" as one word, a
 * trailing remaster note dropped), the credited search first.
 */
export type LookupPlanInput = {
    /** `catalog`: an existing Album, looked up by its saved title (`tags.album`) and `credited` names only. */
    trigger: 'submitted' | 'tags' | 'folder' | 'catalog';
    submitted?: { kind: 'album' | 'song'; text: string };
    /** Credited Artist names given as a list (catalog reviews): never split on ` / `, never read as labels. */
    credited?: readonly string[];
    tags?: { album: string | null; albumArtist: string | null; title: string | null; artist: string | null };
    folderName?: string | null;
    fileCount: number;
    /** Values shared by every selected file. */
    identifiers?: { releaseId?: string | null; barcode?: string | null; catalogNumber?: string | null; isrc?: string | null };
};
/** `fallback`: the fallbacks after a search are sent together, only when the run has no candidate as they start (lookupRunStep.ts). */
export type PlannedLookupQuery =
    | { kind: 'musicBrainzRelease'; releaseId: string; basis: 'releaseId' }
    | { kind: 'musicBrainzReleaseSearch'; query: MusicBrainzReleaseQuery; basis: 'barcode' | 'catalogNumber' | 'albumText' | 'folder'; fallback?: true }
    | { kind: 'musicBrainzRecordingSearch'; query: MusicBrainzRecordingQuery; basis: 'songText'; fallback?: true }
    | { kind: 'musicBrainzIsrc'; isrc: string; basis: 'isrc' };
export type LookupPlan = { queries: PlannedLookupQuery[]; rejected: null | 'url' | 'tooLong' | 'invalidText' | 'empty' };

const term = (value: unknown): string | null => {
    try { return cleanLookupTerm(value, METADATA_LOOKUP_LIMITS.termLength); } catch { return null; }
};
/** Cleaned tag or folder text: format characters (a pasted U+200B, a BOM) are removed and control characters become spaces. */
const tagTerm = (value: unknown): string | null => typeof value === 'string' && value.length <= 4 * METADATA_LOOKUP_LIMITS.termLength + 64
    ? term(value.replace(/\p{Cf}/gu, '').replace(/\p{Cc}/gu, ' ')) : null;

/** Whether a stored planned query is a fallback (another release's shape without the flag is not). */
export const isFallbackLookupQuery = (query: unknown): boolean =>
    typeof query === 'object' && query !== null && (query as { fallback?: unknown }).fallback === true;

const waveDash = /\u301c/gu;
const soundTrack = /\bsound[\s-]+track(s?)\b/giu;
/** A trailing remaster note: `(2013 Remaster)`, `[Remastered]`, ` - Remastered 2009`, `(2011 Remastered Version)`. Anchored and linear. */
const remasterNote = /\s*(?:[([]\s*|\s-\s+)(?:\d{4}\s+)?(?:digital(?:ly)?\s+)?remaster(?:ed)?(?:\s+(?:version|edition))?(?:\s+\d{4})?\s*[)\]]?\s*$/iu;

/**
 * The normalized spelling of cleaned tag or folder text that MusicBrainz titles tend to use: NFKC (full-width forms and `～` fold),
 * the wave dash as `~`, "Sound Track" as "Soundtrack" and a trailing remaster note removed, then cleaned again. Null when it is the
 * cleaned text itself or unusable. Submitted text never gets one: the administrator's own text is sent as typed.
 */
export const normalizedLookupTitle = (text: unknown): string | null => {
    // Cleaned first, so whitespace runs are single spaces and the text is bounded before any pattern runs on it.
    const cleaned = tagTerm(text);
    if (!cleaned) return null;
    const variant = tagTerm(cleaned.normalize('NFKC').replace(waveDash, '~').replace(soundTrack, 'Soundtrack$1').replace(remasterNote, ''));
    return variant && variant !== cleaned ? variant : null;
};

const companySuffix = /(?:^|[\s,(])(?:records|recordings|entertainment|games|studios?|inc\.?|incorporated|ltd\.?|limited|llc|llp|plc|gmbh|k\.k\.|corp\.?|corporation|co\.,?\s*ltd\.?|co\.)(?=$|[\s,.)])/i;
const japaneseCompany = /株式会社|有限会社|合同会社|\(株\)|（株）|レコード|レコーズ|エンタテインメント|エンターテインメント/;

/** Heuristic for a label credited beside artists, such as `Asylum Records` or `株式会社Yostar`. */
export const isCompanyLikeName = (name: string): boolean => companySuffix.test(name) || japaneseCompany.test(name);

/** Splits a credited-names tag on ` / ` only; company-like fragments become label terms and placeholders are dropped. */
export const splitCreditedNames = (text: string | null | undefined): { artists: string[]; labels: string[] } => {
    const artists: string[] = [], labels: string[] = [];
    for (const fragment of (text ?? '').split(' / ')) {
        const name = tagTerm(fragment);
        if (!name || isPlaceholderCredit(name)) continue;
        (isCompanyLikeName(name) ? labels : artists).push(name);
    }
    return { artists, labels };
};

const formatToken = /^(?:\d{4}|flac|mp3|320|320k|320kbps|web|cd|hi-res|hires|24bit|16bit|24-bit|16-bit|\d{2,3}(?:\.\d)?khz|24-\d{2,3}|16-\d{2,3})$/i;

/** Removes bracketed year and format groups such as `[FLAC 24bit/96kHz]` or `(2017)`, then cleans the name. */
export const cleanFolderName = (name: string | null | undefined): string | null => {
    if (typeof name !== 'string' || name.length > 1024) return null;
    const stripped = name.replace(/\[([^[\]()]*)\]|\(([^[\]()]*)\)/g, (group, square: string | undefined, round: string | undefined) => {
        const tokens = (square ?? round ?? '').split(/[\s,/+_]+/).filter(Boolean);
        return tokens.length && tokens.every(token => formatToken.test(token)) ? ' ' : group;
    });
    return tagTerm(stripped);
};

/** A combined query longer than the MusicBrainz query bound is dropped rather than sent truncated. */
const buildable = (query: PlannedLookupQuery) => {
    if (query.kind !== 'musicBrainzReleaseSearch' && query.kind !== 'musicBrainzRecordingSearch') return true;
    try { musicBrainzLuceneQuery(query.query); return true; } catch { return false; }
};

const canonical = (value: unknown): string => {
    if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
    if (value && typeof value === 'object') return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
    return JSON.stringify(value);
};

export const planMetadataLookup = (input: LookupPlanInput): LookupPlan => {
    if (input.trigger === 'submitted' && input.submitted) {
        const problem = lookupTermProblem(input.submitted.text, METADATA_LOOKUP_LIMITS.termLength);
        if (problem === 'url' || problem === 'tooLong' || problem === 'invalidText') return { queries: [], rejected: problem };
    }
    const queries: PlannedLookupQuery[] = [];
    const tags = input.tags;
    // A credited list is cleaned name by name; placeholders are dropped, so the first usable name is the one sent.
    const credited = input.credited
        ? { artists: input.credited.map(tagTerm).filter((name): name is string => !!name && !isPlaceholderCredit(name)), labels: [] as string[] }
        : splitCreditedNames(tags?.albumArtist ?? tags?.artist ?? null);
    const songArtist = input.credited ? credited.artists[0] : splitCreditedNames(tags?.artist ?? tags?.albumArtist ?? null).artists[0];
    /**
     * Credited then bare release text, then with `normalize` the fallbacks in the normalized spelling: the credited search
     * respelled, then the bare text respelled, except a folder's whole "Artist - Album" name, which names no release.
     */
    const releaseQueries = (bare: string, basis: 'albumText' | 'folder', creditedQuery: MusicBrainzReleaseQuery | null, normalize: boolean) => {
        const search = (query: MusicBrainzReleaseQuery, fallback: boolean) =>
            queries.push({ kind: 'musicBrainzReleaseSearch', query, basis, ...(fallback ? { fallback: true as const } : {}) });
        if (creditedQuery) search(creditedQuery, false);
        search({ release: bare }, false);
        if (!normalize) return;
        const creditedVariant = creditedQuery?.release ? normalizedLookupTitle(creditedQuery.release) : null;
        if (creditedQuery && creditedVariant) search({ ...creditedQuery, release: creditedVariant }, true);
        const bareVariant = basis === 'folder' && creditedQuery ? null : normalizedLookupTitle(bare);
        if (bareVariant) search({ release: bareVariant }, true);
    };
    const albumQueries = (release: string, normalize: boolean) => {
        const [artist, label] = [credited.artists[0], credited.labels[0]];
        releaseQueries(release, 'albumText', artist || label ? { release, ...(artist ? { artist } : {}), ...(label ? { label } : {}) } : null, normalize);
    };
    /** Credited then bare recording text, then with `normalize` both again in the normalized spelling as fallbacks. */
    const songQueries = (recording: string, normalize: boolean) => {
        const search = (text: string, fallback: boolean) => {
            const flag = fallback ? { fallback: true as const } : {};
            if (songArtist) queries.push({ kind: 'musicBrainzRecordingSearch', query: { recording: text, artist: songArtist }, basis: 'songText', ...flag });
            queries.push({ kind: 'musicBrainzRecordingSearch', query: { recording: text }, basis: 'songText', ...flag });
        };
        search(recording, false);
        const variant = normalize ? normalizedLookupTitle(recording) : null;
        if (variant) search(variant, true);
    };
    const folderQueries = () => {
        const folder = cleanFolderName(input.folderName);
        if (!folder) return;
        const parts = folder.split(' - ');
        const artist = parts.length === 2 ? tagTerm(parts[0]) : null, release = parts.length === 2 ? tagTerm(parts[1]) : null;
        releaseQueries(folder, 'folder', artist && release && !isPlaceholderCredit(artist) ? { artist, release } : null, true);
    };

    const identifiers = input.identifiers ?? {};
    const releaseId = normalizeMusicBrainzId(identifiers.releaseId);
    if (releaseId) queries.push({ kind: 'musicBrainzRelease', releaseId, basis: 'releaseId' });
    const barcode = normalizeGtin(identifiers.barcode);
    if (barcode) queries.push({ kind: 'musicBrainzReleaseSearch', query: { barcode: barcode.digits }, basis: 'barcode' });
    const catalogNumber = tagTerm(identifiers.catalogNumber);
    if (catalogNumber) queries.push({ kind: 'musicBrainzReleaseSearch', query: { catno: catalogNumber, ...(credited.labels[0] ? { label: credited.labels[0] } : {}) }, basis: 'catalogNumber' });
    const isrc = input.fileCount === 1 ? normalizeIsrc(identifiers.isrc) : null;
    if (isrc) queries.push({ kind: 'musicBrainzIsrc', isrc, basis: 'isrc' });

    if (input.trigger === 'submitted') {
        // Submitted text is sent as typed (only normalized), never respelled.
        const submitted = term(input.submitted?.text);
        if (submitted && input.submitted?.kind === 'song') songQueries(submitted, false);
        else if (submitted) albumQueries(submitted, false);
    } else if (input.trigger === 'tags') {
        // One file is looked up by its title, an album by the album tag; without usable tags, the folder name.
        const title = input.fileCount === 1 ? tagTerm(tags?.title) : null;
        const album = tagTerm(tags?.album);
        if (title) songQueries(title, true);
        else if (album) albumQueries(album, true);
        else folderQueries();
    } else if (input.trigger === 'catalog') {
        // An existing Album is looked up by its saved title only: never a Track title, file name, folder or identifier.
        const album = tagTerm(tags?.album);
        if (album) albumQueries(album, true);
    } else folderQueries();

    // The plan keeps its order: identifiers first, then each text search before its fallbacks, so the cap drops fallbacks first.
    const seen = new Set<string>();
    const unique = queries.filter(buildable).filter(query => {
        // A fallback flag never makes a query distinct: the first of equal queries is kept.
        const key = canonical(query.kind === 'musicBrainzReleaseSearch' || query.kind === 'musicBrainzRecordingSearch' ? { kind: query.kind, query: query.query } : query);
        if (seen.has(key)) return false;
        seen.add(key); return true;
    }).slice(0, METADATA_LOOKUP_LIMITS.plannedQueries);
    return { queries: unique, rejected: unique.length ? null : 'empty' };
};
